GUIDES = [

{
 "slug": "offline-pwa",
 "title": "Build an Installable Offline PWA With No Backend",
 "desc": "How to build an installable offline PWA with no backend: manifest fields, service worker caching, cache versioning, and how iOS install differs.",
 "og_title": "Build an Installable Offline PWA With No Backend",
 "og_desc": "Manifest, service worker caching, cache versioning, storage choice, and how install differs on iOS and Android.",
 "headline": "Building an Installable Offline PWA With No Backend",
 "crumb": "Offline PWA",
 "about": ["Progressive web apps", "Service workers", "Offline-first design"],
 "eyebrow": "Guide · Web",
 "h1": "An installable app, no backend, no app store",
 "lead": "A progressive web app is three files on top of a normal website: a manifest, a service worker, and a storage decision. Get those right and the thing installs to a home screen, launches without a browser chrome, and works on a plane.",
 "level": "Intermediate",
 "nav": NAV_DEV,
 "body": [
  ("h2", "What actually makes a site installable"),
  ("p", "Browsers apply a short checklist before they will offer installation: the site is served over HTTPS, it links a valid web app manifest with the required fields, and it registers a service worker with a fetch handler. Miss any one and the install prompt silently never appears — there is no error, which is why this is the first thing to verify."),
  ("p", "Everything else — offline behaviour, caching strategy, storage — is your design problem, not a requirement. A PWA that installs but breaks offline is worse than a bookmark, so the caching work is where the actual engineering is."),
  ("h2", "The manifest fields that matter"),
  ("p", "A manifest is a small JSON file linked from the head. Most of the spec is optional; a handful of fields decide whether the install looks like an app or looks like a shortcut."),
  ("formula", "&lt;link rel=\"manifest\" href=\"/apps/tradelog/\"&gt;\n\n{\n  \"name\": \"TradeLog\",\n  \"short_name\": \"TradeLog\",\n  \"start_url\": \"/apps/tradelog/\",\n  \"scope\": \"/apps/tradelog/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#0B0B0D\",\n  \"theme_color\": \"#0B0B0D\",\n  \"icons\": [\n    {\"src\": \"icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\"},\n    {\"src\": \"icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\"},\n    {\"src\": \"icon-512-maskable.png\", \"sizes\": \"512x512\",\n     \"type\": \"image/png\", \"purpose\": \"maskable\"}\n  ]\n}"),
  ("ul", ["<strong>start_url</strong> — where the app opens from the home screen. Point it at the app, not at the site root, or every launch lands on your homepage.",
          "<strong>scope</strong> — the URL prefix the app considers its own. Links outside scope open in the browser instead of in the app window.",
          "<strong>display</strong> — <code>standalone</code> removes browser chrome. <code>fullscreen</code> also removes the status bar; <code>minimal-ui</code> keeps a thin bar.",
          "<strong>short_name</strong> — what appears under the icon. Over about 12 characters it gets truncated on a phone.",
          "<strong>icons</strong> — 192px and 512px PNGs at minimum, plus a <code>maskable</code> variant with roughly 20% safe padding so Android does not crop your logo into a circle.",
          "<strong>background_color</strong> — the splash colour while the app boots. Set it to your real background or the launch flashes white."]),
  ("h3", "Manifest field reference"),
  ("table", (["Field", "Needed?", "What it does", "The common mistake"],
             [["<code>name</code>", "Required", "Full app name on the install prompt and splash screen", "Left as the site title, so the prompt offers to install a portfolio"],
              ["<code>short_name</code>", "Strongly advised", "The label under the home-screen icon", "Longer than about 12 characters, so it truncates with an ellipsis"],
              ["<code>start_url</code>", "Required", "The URL opened when the icon is tapped", "Set to <code>/</code>, so every launch lands on the site homepage"],
              ["<code>scope</code>", "Advised", "URL prefix the app treats as its own", "Narrower than <code>start_url</code>, which breaks the app on launch"],
              ["<code>display</code>", "Required for install", "<code>standalone</code>, <code>fullscreen</code>, <code>minimal-ui</code> or <code>browser</code>", "<code>browser</code>, which makes installing pointless"],
              ["<code>display_override</code>", "Optional", "Ordered list of display modes tried before <code>display</code>", "Used without leaving a valid <code>display</code> fallback behind it"],
              ["<code>icons</code>", "Required", "192px and 512px PNGs at minimum", "No <code>maskable</code> variant, so Android crops the logo into a circle"],
              ["<code>background_color</code>", "Advised", "Splash background before the first paint", "White against a dark app — a flash on every single launch"],
              ["<code>theme_color</code>", "Advised", "Tint of the OS status or title bar", "Different from the page's <code>theme-color</code> meta, so the bar changes colour after load"],
              ["<code>id</code>", "Optional", "Stable identity independent of <code>start_url</code>", "Omitted, so changing <code>start_url</code> later installs a second app beside the first"],
              ["<code>orientation</code>", "Optional", "Locks portrait or landscape", "Locked when the layout works fine either way"],
              ["<code>shortcuts</code>", "Optional", "Long-press menu entries pointing at deep links", "Shipped without per-shortcut icons, so entries render blank on some launchers"]])),
  ("p", "Two of those are worth setting even though almost nobody does. <code>id</code> pins the app's identity, so changing <code>start_url</code> a year later updates the installed app instead of quietly installing a second copy next to it. <code>display_override</code> is the only safe way to ask for anything newer than <code>standalone</code>, because browsers that do not recognise the value fall through to <code>display</code> instead of refusing the manifest."),
  ("h2", "Service worker caching strategies"),
  ("p", "A service worker is a script that sits between the app and the network and can answer requests from a cache. There are two strategies worth learning and one rule for choosing between them: <strong>cache-first for things that rarely change, network-first for things that do.</strong>"),
  ("table", (["Strategy", "How it works", "Use it for"],
             [["Cache-first", "Serve from cache; only hit the network on a miss", "App shell: HTML, CSS, JS, icons, fonts"],
              ["Network-first", "Try the network; fall back to cache on failure", "API responses, prices, anything time-sensitive"],
              ["Stale-while-revalidate", "Serve cache immediately, refresh cache in background", "Content that can be one version old without harm"],
              ["Network-only", "Never cache", "Analytics, POSTs, anything with side effects"]])),
  ("p", "For an app with no backend, this collapses nicely: everything is app shell, so almost everything is cache-first, and there is no data endpoint to worry about because the data lives in the browser."),
  ("formula", "const CACHE = 'tradelog-v7';\nconst SHELL = ['/apps/tradelog/', '/apps/tradelog/index.html',\n               '/apps/tradelog/app.js', '/apps/tradelog/app.css'];\n\nself.addEventListener('install', e =&gt; {\n  e.waitUntil(caches.open(CACHE).then(c =&gt; c.addAll(SHELL)));\n  self.skipWaiting();\n});\n\nself.addEventListener('activate', e =&gt; {\n  e.waitUntil(\n    caches.keys().then(keys =&gt; Promise.all(\n      keys.filter(k =&gt; k !== CACHE).map(k =&gt; caches.delete(k))\n    )).then(() =&gt; self.clients.claim())\n  );\n});\n\nself.addEventListener('fetch', e =&gt; {\n  e.respondWith(caches.match(e.request).then(r =&gt; r || fetch(e.request)));\n});"),
  ("h2", "Cache versioning, and the classic bug"),
  ("p", "The single most common PWA bug: <strong>you ship a fix, users reload, and they still see the old app.</strong> This is not a mystery, it is the service worker lifecycle working as designed. A new worker installs but stays in a <em>waiting</em> state until every tab controlled by the old one is closed — and reloading a tab does not close it."),
  ("ol", ["<strong>Bump the cache name on every deploy.</strong> <code>tradelog-v6</code> becomes <code>tradelog-v7</code>. If the name does not change, <code>addAll</code> writes into the same bucket and old entries survive.",
          "<strong>Delete old caches in <code>activate</code>.</strong> Otherwise every version you ever shipped stays on the user's disk forever.",
          "<strong>Call <code>skipWaiting()</code> and <code>clients.claim()</code></strong> so the new worker takes over immediately instead of waiting for all tabs to close.",
          "<strong>Never cache the service worker file itself with a long max-age.</strong> If <code>sw.js</code> is cached by the HTTP layer, the browser cannot see that it changed, and the app is frozen until the cache header expires."]),
  ("warn", "The failure mode is silent and it looks like your deploy did not work. Before debugging your build, open DevTools → Application → Service Workers and check whether a worker is stuck in <em>waiting</em>. That is the answer roughly nine times out of ten."),
  ("h3", "The lifecycle, as a table"),
  ("p", "Everything above is one instance of a fixed state machine every service worker goes through. Knowing the five states by name makes the waiting-worker bug obvious instead of mysterious."),
  ("table", (["State", "What puts it there", "What you can do here"],
             [["<code>installing</code>", "register() resolves and the script downloads and parses", "Populate the cache inside the install event — the only safe place to call addAll()"],
              ["<code>installed</code> / <code>waiting</code>", "Install finished, but an existing worker still controls open tabs", "Nothing happens here unless skipWaiting() is called or every controlled tab is closed"],
              ["<code>activating</code>", "No client still needs the old worker, or skipWaiting() forced the transition", "Delete stale caches inside the activate event, before the new worker takes requests"],
              ["<code>activated</code>", "Activation finished", "The worker now controls fetch events for everything in its scope"],
              ["<code>redundant</code>", "A newer worker replaced it, or install or activate threw an exception", "Nothing — it is discarded permanently and never runs again"]])),
  ("p", "Two of those five states are where deploys go wrong in practice: a worker parked in <em>waiting</em> because nothing ever called skipWaiting(), or a worker that jumps straight to <em>redundant</em> because an uncaught exception fired during install and nobody was watching the console."),
  ("h2", "Prompting the user before you reload their app"),
  ("p", "Calling skipWaiting() and clients.claim() unconditionally, the way the caching example above does, updates the app the instant a new worker installs — including mid-session, under the user's fingers. For a checklist that is harmless. For a trade journal with an open, unsaved entry, an unannounced reload is worse than the stale-version bug it fixes. The alternative is to let the new worker wait, then ask."),
  ("formula", "// sw.js — wait for explicit permission instead of skipping automatically\nself.addEventListener('install', e =&gt; {\n  e.waitUntil(caches.open(CACHE).then(c =&gt; c.addAll(SHELL)));\n});\n\nself.addEventListener('message', e =&gt; {\n  if (e.data &amp;&amp; e.data.type === 'SKIP_WAITING') self.skipWaiting();\n});\n\n// app.js — detect the waiting worker, show a banner, reload once and only once\nlet reloaded = false;\nnavigator.serviceWorker.addEventListener('controllerchange', () =&gt; {\n  if (reloaded) return;\n  reloaded = true;\n  window.location.reload();\n});\n\nnavigator.serviceWorker.register('/sw.js').then(reg =&gt; {\n  reg.addEventListener('updatefound', () =&gt; {\n    const worker = reg.installing;\n    worker.addEventListener('statechange', () =&gt; {\n      if (worker.state === 'installed' &amp;&amp; navigator.serviceWorker.controller) {\n        showUpdateBanner(() =&gt; worker.postMessage({type: 'SKIP_WAITING'}));\n      }\n    });\n  });\n});"),
  ("p", "The controllerchange listener needs the guard flag because it can fire more than once in edge cases, and a second unexpected reload is its own bug report. Use the unconditional auto-update from the caching example for something as disposable as a daily checklist; use the ask-first pattern for anything holding state a reload could destroy."),
  ("h2", "localStorage or IndexedDB?"),
  ("p", "Both keep data on the user's device. They are not interchangeable."),
  ("table", (["", "localStorage", "IndexedDB"],
             [["API", "Synchronous, three methods, trivial", "Asynchronous, transactional, verbose"],
              ["Data type", "Strings only — you JSON round-trip everything", "Structured objects, blobs, files"],
              ["Practical size", "About 5 MB per origin", "Large — typically a share of free disk"],
              ["Querying", "None. You load everything and filter in JS", "Indexes and cursors"],
              ["Blocking", "Blocks the main thread on every read and write", "Off the main thread"]])),
  ("p", "The rule I use: <strong>localStorage until it hurts.</strong> A few thousand records of JSON is fine — a trade journal, a weight log, a habit checklist. Move to IndexedDB when you are storing binary data, when you need to query rather than load-everything-and-filter, or when the payload passes a megabyte or two and the synchronous writes start showing up as jank."),
  ("p", 'One caveat for either: browser storage is not backup. It survives reloads and reboots, but it does not survive a cleared browsing history, and on iOS it can be evicted after extended non-use. Ship an export button and say so plainly — the same principle is argued more generally in <a href="/guides/client-side-only-tools.html">the client-side-only tools guide</a>.'),
  ("h3", "How much storage you actually get"),
  ("p", "The eviction risk above is not uniform across browsers, and it is worth knowing the real numbers instead of guessing at them."),
  ("table", (["Browser", "Typical quota", "Eviction trigger"],
             [["Chrome / Edge (desktop)", "Up to roughly 60% of free disk space, shared across an origin's storage", "Least-recently-used origin evicted only once the disk is genuinely full"],
              ["Firefox", "Up to roughly 50% of free disk space, group-limited per site", "Similar LRU eviction, only under real disk pressure"],
              ["Safari, installed to home screen", "On the order of 1 GB in practice, not formally documented", "Can be cleared after roughly a week or more without the app being opened, or by the OS under storage pressure"],
              ["Safari, ordinary tab", "Same rough ceiling as installed", "Also subject to Intelligent Tracking Prevention's separate script-writable storage cap"]])),
  ("p", "Query the real number instead of assuming one: <code>navigator.storage.estimate()</code> returns usage and quota for the current origin, and <code>navigator.storage.persist()</code> requests exemption from automatic eviction — a request, not a guarantee, and Safari in particular can still ignore it."),
  ("formula", "const { usage, quota } = await navigator.storage.estimate();\nconsole.log(`${(usage / quota * 100).toFixed(1)}% of quota used`);\n\nconst granted = await navigator.storage.persist();"),
  ("h2", "Installing on iOS versus Android"),
  ("p", "This is the part that costs support emails, because the two platforms behave completely differently and only one of them tells the user anything."),
  ("ul", ["<strong>Android Chrome</strong> — the browser detects installability and surfaces its own prompt. You can also capture the <code>beforeinstallprompt</code> event and trigger it from your own button, which converts far better than waiting for the browser banner.",
          "<strong>iOS Safari</strong> — there is no prompt and no <code>beforeinstallprompt</code> event. The user must tap <strong>Share → Add to Home Screen</strong> manually. Nothing on the page can trigger it.",
          "<strong>iOS third-party browsers</strong> — Chrome and Firefox on iOS have historically been unable to add a PWA to the home screen at all. If a user says the option is missing, ask which browser they are in before anything else.",
          "<strong>Detecting installed state</strong> — <code>window.matchMedia('(display-mode: standalone)')</code> works broadly; iOS also exposes <code>navigator.standalone</code>."]),
  ("h3", "Capturing the install prompt yourself"),
  ("p", "The browser's own install banner converts poorly because it interrupts at a moment you do not control. Capturing the event and firing it from your own button, after a return visit or a first save, converts meaningfully better."),
  ("formula", "let deferredPrompt = null;\n\nwindow.addEventListener('beforeinstallprompt', (e) =&gt; {\n  e.preventDefault();\n  deferredPrompt = e;\n  installButton.hidden = false;\n});\n\ninstallButton.addEventListener('click', async () =&gt; {\n  installButton.hidden = true;\n  deferredPrompt.prompt();\n  const { outcome } = await deferredPrompt.userChoice;\n  console.log(outcome); // 'accepted' or 'dismissed'\n  deferredPrompt = null;\n});\n\nwindow.addEventListener('appinstalled', () =&gt; {\n  deferredPrompt = null;\n});"),
  ("p", "Practical consequence: detect iOS Safari and show a small one-line instruction with the share icon, and hide it once the app is running in standalone mode. Without that hint, most iPhone users will never install."),
  ("h3", "What iOS does not support"),
  ("p", "Safari implements enough of the spec to install and run offline, and stops well short of what Android Chrome offers. Budget for the gap instead of discovering it in a support thread."),
  ("table", (["Capability", "iOS Safari", "Note"],
             [["Install prompt", "No prompt, no beforeinstallprompt", "Manual Share → Add to Home Screen only"],
              ["Web push notifications", "iOS 16.4 and later only", "Requires the app to already be installed to the home screen — no push before that"],
              ["Background sync", "Not implemented", "No deferred retry when connectivity returns"],
              ["Periodic background sync", "Not implemented", "No scheduled background refresh"],
              ["Badging API", "Partial, version-dependent", "Do not build a feature that depends on it working everywhere"],
              ["Share Target", "Not implemented", "The app can share out; it cannot receive an incoming share"],
              ["Storage durability", "Better once installed, still not permanent", "Extended non-use can still evict data — see the quota table above"]])),
  ("h2", "Offline fallback pages"),
  ("p", "Cache-first serves the shell offline, but a navigation to a URL that was never cached — a deep link opened cold, with no connection — still fails outright unless something catches it. A dedicated offline page turns a browser error screen into something that explains itself."),
  ("formula", "const OFFLINE_URL = '/offline.html';\n\nself.addEventListener('install', e =&gt; {\n  e.waitUntil(caches.open(CACHE).then(c =&gt; c.addAll([...SHELL, OFFLINE_URL])));\n});\n\nself.addEventListener('fetch', e =&gt; {\n  if (e.request.mode === 'navigate') {\n    e.respondWith(\n      fetch(e.request).catch(() =&gt; caches.match(OFFLINE_URL))\n    );\n    return;\n  }\n  e.respondWith(caches.match(e.request).then(r =&gt; r || fetch(e.request)));\n});"),
  ("p", "Checking <code>e.request.mode === 'navigate'</code> matters: applying the fallback to every failed request would swap a failed image or a failed background fetch for an entire HTML page. Scope the fallback to page navigations only, and let everything else fail the ordinary way."),
  ("h2", "A debugging checklist, in order"),
  ("p", "Almost every PWA bug report reduces to one of these, checked in this order because each one hides the next."),
  ("ol", ["<strong>Confirm HTTPS.</strong> Local development over http://localhost is exempt; anywhere else, no service worker registers without it.",
          "<strong>Open DevTools → Application → Manifest</strong> and read the errors panel. A single invalid field can silently disqualify installability.",
          "<strong>Open DevTools → Application → Service Workers</strong> and check the status. A worker stuck in waiting is the single most common complaint, and the fix is the update pattern above.",
          "<strong>Check the scope.</strong> A worker registered from <code>/app/sw.js</code> only controls <code>/app/</code> and below, never a URL outside that prefix.",
          "<strong>Inspect Cache Storage</strong> for stale entries sitting under an old cache name — proof that the activate cleanup step either never ran or never shipped.",
          "<strong>Run a Lighthouse PWA audit.</strong> It checks the installability criteria directly and names the missing field instead of leaving you to guess.",
          "<strong>As a last resort, unregister and hard-reload.</strong> This clears local state a real user cannot easily clear, and separates 'my code is wrong' from 'my browser's cache is stale'."]),
  ("h2", "What you give up"),
  ("p", "No App Store listing and no App Store search traffic. No push notifications on iOS unless the app has been added to the home screen. No background execution to speak of. Nothing that requires a native API the browser has not exposed."),
  ("p", 'What you get in exchange: zero platform fees, no review queue, no annual developer fee, and a deploy that reaches every user the moment you push. For a personal tool, that trade is usually correct. I ship three of these on the <a href="/apps.html">apps hub</a> — <a href="/apps/tradelog/">TradeLog</a>, <a href="/apps/cut/">Cut</a>, and <a href="/apps/fire/">Fire</a> — all offline, all local storage, no accounts anywhere, on the same static-hosting setup described in <a href="/stack.html">my stack</a>.'),
 ],
 "tools": [("/apps.html", "Apps hub", "the three installable PWAs, all offline and account-free."),
           ("/apps/tradelog/", "TradeLog", "R-multiple trading journal — a localStorage-backed PWA in production."),
           ("/apps/fire/", "Fire", "daily ritual checklist, the smallest of the three and the clearest example of the pattern."),
           ("/privacy.html", "Privacy policy", "how the local-only storage claim is written up for users.")],
 "faqs": [
  ("What makes a website installable as a PWA?", "Three things: it is served over HTTPS, it links a valid web app manifest with name, icons, start_url and display, and it registers a service worker with a fetch handler. If any one is missing the browser simply never offers installation, with no error message shown."),
  ("What is the difference between cache-first and network-first?", "Cache-first serves from the cache and only touches the network on a miss, which suits the app shell — HTML, CSS, JS and icons that change only on deploy. Network-first tries the network and falls back to the cache, which suits data that goes stale, like prices or API responses."),
  ("Why do users still see the old version after I deploy a PWA?", "Because the new service worker installs but stays in a waiting state until every tab controlled by the old one is closed, and reloading a tab does not close it. Fix it by bumping the cache name on every deploy, deleting old caches during the activate event, and calling skipWaiting() plus clients.claim()."),
  ("Should I use localStorage or IndexedDB?", "Use localStorage for small amounts of JSON — a few thousand records is comfortable within its roughly 5 MB limit. Move to IndexedDB when you need to store binary data, query with indexes instead of loading everything, or when synchronous writes start causing visible jank."),
  ("How do you install a PWA on an iPhone?", "Open the site in Safari, tap the Share button, then choose Add to Home Screen. iOS provides no automatic install prompt and no beforeinstallprompt event, so the page cannot trigger it — and third-party browsers on iOS have historically not offered the option at all."),
  ("Can a PWA work with no backend at all?", "Yes. If all state lives in the user's browser through localStorage or IndexedDB and the service worker caches the app shell, there is nothing left for a server to do beyond serving static files. That also means no accounts, no sync, and no server-side compute."),
  ("How do you avoid reloading a PWA out from under the user?", "Do not call skipWaiting() unconditionally. Let the new worker sit in the waiting state, listen for the updatefound and statechange events to detect it, show a banner, and only call skipWaiting() through postMessage once the user agrees. Guard the resulting controllerchange reload with a flag so it only fires once."),
  ("How much storage does a PWA actually get?", "Chrome and Firefox typically allow up to 50 to 60 percent of free disk space per origin, evicted only under real disk pressure. Safari's effective ceiling is closer to 1 gigabyte and can be evicted after roughly a week or more of the app not being opened, even when installed. Call navigator.storage.estimate() to read the real number instead of assuming one."),
 ],
},

{
 "slug": "client-side-only-tools",
 "title": "The Case for Client-Side-Only Tools",
 "desc": "No account means no breach surface. What you gain from browser-only tools, what you give up in sync and compute, what it costs to run, and how to say so.",
 "og_title": "The Case for Client-Side-Only Tools",
 "og_desc": "No accounts, no database, no breach surface — and an honest account of what that costs the user.",
 "headline": "The Case for Client-Side-Only Tools",
 "crumb": "Client-Side Tools",
 "about": ["Local-first software", "Privacy by design", "Static hosting"],
 "eyebrow": "Guide · Architecture",
 "h1": "Tools with no backend, and the honest trade",
 "lead": "A tool that never sends data anywhere cannot leak it, cannot lose it in someone else's breach, and cannot be repriced when the hosting bill arrives. It also cannot sync to your phone. Both halves are worth saying out loud.",
 "level": "Beginner",
 "nav": NAV_DEV,
 "body": [
  ("h2", "The default is heavier than the problem"),
  ("p", "Most small utilities get built with an account system, a database, a session store, and a hosting bill — for a calculator. The reflex is so automatic that nobody asks whether the server is doing anything the browser could not."),
  ("p", "For a large class of tools, it is not. A position sizer, a trade journal, a weight tracker, a habit checklist, a unit converter, a text formatter: all of these are pure functions plus a little state. The browser has a JavaScript engine and persistent storage. That is the entire requirement."),
  ("h2", "Which tools actually need a server"),
  ("p", "The honest test is not \"can this be a website\" — almost anything can. It is whether the feature the tool provides is possible without a second party holding state. A decision table, run once per tool, saves the account system nobody needed."),
  ("table", (["Tool type", "Needs a server", "Why"],
             [["Calculator, converter, position sizer", "No", "Pure function of the inputs. Nothing to persist across a session at all."],
              ["Trade journal, habit tracker, weight log", "No", "State is single-user and can live entirely in browser storage."],
              ["Unit or file conversion (images, text, small media)", "No", "JavaScript or WebAssembly can do the transform in the browser."],
              ["Team task board, shared document", "Yes", "Multiple people must see the same state, which requires a relay."],
              ["Chat or messaging", "Yes", "Delivery to someone else's device requires a server in the middle."],
              ["Marketplace or listings app", "Yes", "Inventory must stay consistent across every buyer viewing it."],
              ["Anything calling a paid API with a secret key", "Yes", "A key embedded in browser JS is public the moment the page loads."],
              ["Anything that must survive a lost or wiped device", "Yes, or strict export discipline", "A server-side copy is the only unconditional guarantee."],
              ["Cross-device sync as a hard requirement", "Yes, or an opt-in sync layer", "Covered later — this does not have to mean starting over."]])),
  ("h2", "What you gain"),
  ("h3", "No breach surface"),
  ("p", "The strongest security property available is <strong>not holding the data.</strong> No user table means no credential dump, no password reset flow to phish, no session tokens to steal, no compliance obligation around personal data you never received. You cannot be forced to hand over records that were never on your server, and an attacker who fully compromises the host gets a folder of static files."),
  ("h3", "Data stays where the user can see it"),
  ("p", "Browser storage is inspectable. A curious user can open DevTools and read exactly what the app kept. That is a much stronger claim than a privacy policy, because it is verifiable rather than promised — the network tab shows there are no outbound requests carrying their data."),
  ("h3", "It costs nothing to run"),
  ("p", "Static files on GitHub Pages, Netlify, or Cloudflare Pages cost nothing at realistic personal-project traffic. There is no database to back up, no dependency to patch at 2am, no bill that grows with users. A client-side tool that gets popular gets <em>cheaper</em> per user, not more expensive."),
  ("h3", "It keeps working"),
  ("p", 'No server means no outage, no rate limit, no deprecation. Offline through a service worker, it works on a plane — the mechanics of that are in the <a href="/guides/offline-pwa.html">offline PWA guide</a>. A tool built this way in 2020 still runs today with no maintenance, which is not a claim most SaaS side projects can make.'),
  ("h3", "Choosing a storage mechanism"),
  ("p", "\"Browser storage\" is not one thing. Picking the wrong one shows up later as either a size ceiling or a jank problem, both avoidable up front."),
  ("table", (["Mechanism", "Persists after tab close", "Practical size", "Sync to server", "Use it for"],
             [["Cookies", "Yes", "About 4 KB per cookie", "Sent automatically on every request", "Server communication, not app state — the wrong tool for local-only data"],
              ["sessionStorage", "No, cleared on tab close", "About 5 MB", "None", "Transient in-page state, never saved data"],
              ["localStorage", "Yes", "About 5 MB per origin", "None", "Small JSON — journals, logs, settings, a few thousand records"],
              ["IndexedDB", "Yes", "Large, a share of free disk", "None", "Structured or binary data, real queries, anything past a couple MB"],
              ["Cache API", "Yes", "Large", "None", "Network responses and assets behind a service worker, not app data"],
              ["Origin Private File System", "Yes", "Large", "None", "Fast binary file access; newer, support still catching up"]])),
  ("h2", "What you give up"),
  ("p", "This is the part most local-first pitches skip, so here it is plainly."),
  ("table", (["You lose", "What that means in practice"],
             [["Cross-device sync", "Data logged on the laptop is not on the phone. Two devices means two separate datasets."],
              ["Backup", "Clearing browser data deletes everything. On iOS, storage can be evicted after long non-use."],
              ["Server-side compute", "No heavy jobs, no scheduled tasks, no calling a paid API without exposing the key."],
              ["Collaboration", "No sharing, no multi-user, no permissions — there is nothing to share through."],
              ["Analytics on usage", "You genuinely do not know how the tool is used, which makes it harder to improve."],
              ["Recovery", "No support ticket can restore what a user deleted, because you never had a copy."]])),
  ("p", "The honest framing is not that these do not matter. It is that <strong>for single-user tools they usually matter less than the ongoing cost of an account system</strong> — for the builder and for the user, who has one more password and one more breach notification in their future."),
  ("h2", "The honest threat model"),
  ("p", "\"Local-only\" is not a synonym for \"secure.\" State plainly what the architecture protects against and what it does not — overclaiming here is exactly the kind of promise that erodes trust the moment someone technical tests it."),
  ("table", (["Threat", "Protected?", "Why"],
             [["Server-side data breach", "Yes", "There is no server-side copy of user data to breach"],
              ["Database credential leak", "Yes", "There is no database"],
              ["Password reuse or credential stuffing", "Yes", "There is no password, because there is no account"],
              ["XSS on your own domain", "No", "A script injected into the page reads localStorage and IndexedDB with the same access your own code has"],
              ["Malicious or compromised browser extension", "No", "Extensions with broad permissions can read page-accessible storage like any other script"],
              ["Shared or public device", "No", "Anyone with access to the browser profile can open DevTools and read everything stored"],
              ["Physical device theft, unencrypted disk", "No", "Browser storage is not encrypted by the browser itself; disk encryption is a separate, OS-level setting"],
              ["Compromised third-party script or CDN dependency", "No", "A compromised script runs with the same privileges as the rest of the page"]])),
  ("p", 'The defence against every "No" row is ordinary web security hygiene, not anything specific to local-first: a strict Content-Security-Policy, subresource integrity on third-party scripts, sanitising anything rendered as HTML, and treating browser extensions as ambient risk outside your control. None of that becomes optional just because there is no server to also secure — the client is now the entire attack surface rather than a thin layer in front of one, which is exactly the case a tool like <a href="/dira.html">DIRA</a> is built to scan for.'),
  ("h2", "Mitigations that keep the model intact"),
  ("ol", ["<strong>Ship export and import.</strong> A JSON or CSV download turns 'no backup' into 'your backup, your file'. This is the single highest-value feature in a local-only tool.",
          "<strong>Warn before destructive actions</strong> and never auto-clear storage on version change.",
          "<strong>Make the storage key stable</strong> across deploys, and migrate schemas forward rather than resetting them.",
          "<strong>Say where the data lives, in the app,</strong> not only in the privacy policy. One line under the form does more than a page nobody opens.",
          "<strong>If sync is genuinely needed later,</strong> add it as an opt-in layer over the same local store rather than rewriting around a server."]),
  ("h2", "Schema versioning, worked"),
  ("p", "\"Migrate schemas forward\" above is the mitigation people skip, because it sounds like more work than it is. Here is what it looks like end to end, for a tracker that adds a <code>unit</code> field in version 2 that version 1 records never had."),
  ("formula", "const STORE_KEY = 'cut-tracker';\nconst CURRENT_VERSION = 2;\n\nconst MIGRATIONS = {\n  1: (data) =&gt; data, // baseline, nothing to do\n  2: (data) =&gt; ({\n    ...data,\n    entries: data.entries.map(e =&gt; ({ ...e, unit: e.unit || 'lb' })),\n  }),\n};\n\nfunction load() {\n  const raw = localStorage.getItem(STORE_KEY);\n  if (!raw) return { version: CURRENT_VERSION, entries: [] };\n\n  let data = JSON.parse(raw);\n  let v = data.version || 1;\n\n  while (v &lt; CURRENT_VERSION) {\n    v += 1;\n    data = MIGRATIONS[v](data);\n  }\n\n  if (v !== (data.version || 1)) {\n    data.version = v;\n    localStorage.setItem(STORE_KEY, JSON.stringify(data));\n  }\n  return data;\n}"),
  ("p", "Two rules make this safe. Migrations run forward, one version at a time, so a jump from version 1 to version 4 replays three small, individually testable steps instead of one large rewrite. And the migration writes back to storage immediately, so the very next load is already current — which means the migration code for an old version can eventually be deleted once you are confident nobody is still on it."),
  ("h2", "Adding sync later, without a rewrite"),
  ("p", "The last mitigation above deserves the full explanation, because \"add sync later\" sounds harder than it is if the local store was treated as the source of truth from day one."),
  ("ol", ["<strong>Local storage stays the source of truth</strong> even after sync exists. Sync is a mirror, not a replacement — the app must keep working with the network off.",
          "<strong>Sync is an explicit opt-in,</strong> never a silent background upload. A user who never enables it is running the exact same app as before sync existed.",
          "<strong>Sync diffs, not the whole dataset.</strong> Timestamp every record on write, and push only what changed since the last successful sync.",
          "<strong>Pick a conflict rule before you need one.</strong> Last-write-wins by timestamp is simple and fine for single-user data edited from one device at a time; genuinely concurrent editing needs a CRDT or operational-transform library, which is real added complexity, not a checkbox.",
          "<strong>The server side can be minimal.</strong> One authenticated endpoint that accepts and returns a JSON blob per user is enough for years of a single-user tool. It does not need to become a product."]),
  ("formula", "async function sync() {\n  if (!syncEnabled()) return;\n  const last = localStorage.getItem('lastSyncAt') || 0;\n  const dirty = getEntries().filter(e =&gt; e.updatedAt &gt; last);\n\n  if (dirty.length) {\n    await fetch('/api/sync', { method: 'POST', body: JSON.stringify({ entries: dirty }) });\n  }\n  const remote = await fetch('/api/sync?since=' + last).then(r =&gt; r.json());\n  mergeByTimestamp(remote.entries); // last-write-wins on updatedAt\n  localStorage.setItem('lastSyncAt', Date.now());\n}"),
  ("p", "Nothing about this touches the local storage schema, the UI, or any code path a non-syncing user exercises. That is the actual payoff of designing local-first from day one: sync becomes an addition, not a rewrite."),
  ("h2", "What client-side hosting actually costs"),
  ("p", "The zero-cost claim made earlier is worth pricing out explicitly, against the alternative, as an illustrative comparison rather than a quote from any specific host."),
  ("table", (["Host", "Free tier", "What it costs at real personal-project traffic", "Best for"],
             [["GitHub Pages", "Unlimited for public repos", "Effectively $0", "Personal tools, portfolios, static guides"],
              ["Cloudflare Pages", "Unlimited bandwidth on the free plan", "Effectively $0", "Same as GitHub Pages, with a faster edge network"],
              ["Netlify", "100 GB bandwidth per month free", "$0 until traffic passes the free allowance, then billed per GB", "Static tools that also want form handling"],
              ["Vercel", "Generous free tier tuned for frameworks", "$0 until usage forces an upgrade", "If you are already building with a framework it favours"],
              ["Any backend (VM plus managed database)", "Rarely a real free tier", "Roughly $5 to $50+ per month minimum, before any traffic", "Only once a specific feature has proven it needs a server"]])),
  ("p", "The comparison is not close. Static hosting is not merely cheaper than a backend, it is frequently exactly $0 at the traffic a personal tool actually receives, while a backend carries a monthly floor whether or not anyone opens the tool that day."),
  ("h2", "Writing the privacy policy honestly"),
  ("p", "A local-only tool makes for a short, unusually credible privacy policy — but only if it is specific. Vague reassurance reads exactly like every policy that turned out to be false."),
  ("ul", ["Name the storage mechanism: 'stored in your browser's localStorage on this device'.",
          "State plainly that there is no account, no server-side database, and no transmission of entered data.",
          "Disclose what <em>is</em> collected, if anything — static hosting still produces server logs with IP addresses, and any embedded analytics or fonts are third-party requests. Do not claim zero collection while loading a tracker.",
          "Explain the eviction risk: clearing site data deletes it, and browsers may evict storage. Point at the export button in the same sentence.",
          "Skip the legal-sounding padding. A policy a user can read in 60 seconds is more protective than one they cannot."]),
  ("p", 'The test I use: could a technically literate user verify every claim in the policy from the network tab in under a minute? If yes, it is honest. If a claim requires trusting me, it should be softened or removed. <a href="/privacy.html">Mine is here →</a>'),
  ("h2", "When you actually do need a backend"),
  ("p", 'Not every tool fits. You need a server when the data is genuinely shared between people, when compute exceeds what a phone browser can do, when an API key must stay secret, when the data must survive a lost device, or when a regulation requires audit trails you can produce. Those are real requirements — the point is to check whether you have one, not to assume you do. <a href="/apps/cut/">Cut</a>, on the <a href="/stack.html">stack</a> described here, is the small end of the local-only case: a weight tracker with nothing behind it but a browser.'),
 ],
 "tools": [("/apps.html", "Apps hub", "three tools built this way — no accounts, no server, no analytics on your entries."),
           ("/apps/cut/", "Cut", "weight tracker with local storage and an export path."),
           ("/privacy.html", "Privacy policy", "a short, verifiable version of the claims described here."),
           ("/stack.html", "My stack", "what static hosting and tooling this runs on.")],
 "faqs": [
  ("What is a client-side-only tool?", "A tool that runs entirely in the browser, with all state kept in browser storage such as localStorage or IndexedDB, and no server component beyond serving static files. There is no account, no database, and no transmission of what the user enters."),
  ("Is a tool without accounts more secure?", "For the user's data, generally yes, because the strongest protection is not holding the data at all. There is no user table to dump, no session tokens to steal, and no password reset flow to phish. It does not make the code itself more secure, and it offers no protection if the device is compromised."),
  ("What do you lose with no backend?", "Cross-device sync, server-side backup and recovery, collaboration between users, server-side compute, secret API keys, and any real usage analytics. For single-user tools these usually matter less than the cost of running an account system, but they are real losses and should be disclosed."),
  ("What does it cost to run a client-side tool?", "Effectively nothing. Static files on GitHub Pages, Netlify, or Cloudflare Pages are free at personal-project traffic levels, and there is no database to back up or patch. Cost per user falls as usage grows rather than rising."),
  ("How do users back up data in a browser-only app?", "Through an export function that downloads their data as JSON or CSV, which they store themselves. This is the single most important feature in a local-only tool, because clearing site data deletes everything and browsers can evict storage after extended non-use."),
  ("What should a local-only privacy policy say?", "Name the exact storage mechanism, state that there is no account and no server-side database, disclose anything that is still collected such as hosting server logs or third-party fonts and analytics, explain that clearing site data deletes everything, and point at the export button. Every claim should be verifiable from the browser's network tab."),
  ("Does a client-side-only tool protect against XSS?", "No. Cross-site scripting on your own domain reads localStorage and IndexedDB with the same access your own code has, so a local-only architecture protects against a server-side breach but not against a script injected into the page. That defence is ordinary web hygiene — a strict Content-Security-Policy, subresource integrity, and sanitising anything rendered as HTML — not something local-first replaces."),
  ("How do you add sync to a local-only tool without rewriting it?", "Keep local storage as the source of truth, add sync as an explicit opt-in rather than a silent upload, push only records changed since the last sync using a timestamp on each record, and pick a conflict rule upfront — last-write-wins is enough for single-user data edited one device at a time. The server side can be a single endpoint that stores a JSON blob per user; it does not need to become a product."),
 ],
},

{
 "slug": "ffmpeg-auto-editing",
 "title": "Automated Video Editing With ffmpeg",
 "desc": "Scene-change detection, audio-energy highlights, lossless cutting and concatenation, 9:16 vertical conversion, and why a local pipeline beats a cloud API.",
 "og_title": "Automated Video Editing With ffmpeg",
 "og_desc": "Scene detection, audio-energy highlights, cutting, concatenation, and 9:16 conversion — all locally.",
 "headline": "Automated Video Editing With ffmpeg: Detection, Cutting, Vertical",
 "crumb": "ffmpeg Auto-Editing",
 "about": ["ffmpeg", "Video processing", "Automation"],
 "eyebrow": "Guide · Media",
 "h1": "Turning long footage into clips, automatically",
 "lead": "An automatic editor is not one clever algorithm. It is a detector that proposes cut points, a scorer that ranks segments, and a cutter that stitches the winners together — and ffmpeg can do all three from the command line.",
 "level": "Intermediate",
 "nav": NAV_DEV,
 "body": [
  ("h2", "The shape of the pipeline"),
  ("ol", ["<strong>Probe</strong> — read duration, resolution, frame rate, and audio layout so nothing downstream guesses.",
          "<strong>Detect</strong> — find candidate boundaries with scene-change detection and candidate highlights with audio energy.",
          "<strong>Score and select</strong> — rank the candidate segments and pick the ones that fit the target runtime.",
          "<strong>Cut</strong> — extract the selected ranges, ideally without re-encoding.",
          "<strong>Assemble</strong> — concatenate, convert aspect ratio, normalise loudness, encode once at the end."]),
  ("p", "The discipline that keeps this fast is doing all the analysis on cheap passes and <strong>encoding exactly once</strong>, at the end. Every intermediate re-encode costs time and a generation of quality."),
  ("h2", "Probe first"),
  ("formula", "ffprobe -v error -show_entries \\\n  format=duration:stream=width,height,r_frame_rate,codec_type \\\n  -of json input.mp4"),
  ("p", "Hardcoding 1920x1080 at 30fps is how a pipeline breaks on the first phone clip someone hands you. Read it, branch on it."),
  ("h2", "Scene-change detection"),
  ("p", "ffmpeg's <code>select</code> filter exposes a per-frame <code>scene</code> score between 0 and 1, measuring how different a frame is from its predecessor. Thresholding that score gives you cut candidates."),
  ("formula", "ffmpeg -i input.mp4 \\\n  -filter:v \"select='gt(scene,0.4)',showinfo\" \\\n  -f null - 2&gt;&amp;1 | grep showinfo\n\n# print timestamps only, machine-readable\nffprobe -show_frames -of csv=p=0 \\\n  -f lavfi \"movie=input.mp4,select=gt(scene\\,0.4)\" \\\n  -show_entries frame=pkt_pts_time"),
  ("ul", ["<strong>0.3</strong> — sensitive. Fires on camera movement and lighting changes as well as real cuts.",
          "<strong>0.4</strong> — a reasonable default for mixed footage.",
          "<strong>0.5 and above</strong> — hard cuts only. Misses dissolves and slow transitions entirely.",
          "Single continuous shots — a locked-off camera at an event produces almost no scene changes, so this detector contributes nothing and audio has to carry the selection."]),
  ("h3", "Calibrating the threshold by footage type"),
  ("p", "0.4 is a starting point, not a constant. The right threshold depends on how much of the frame moves on a normal cut versus a normal pan, and that varies enormously by source."),
  ("table", (["Footage type", "Reasonable threshold", "Why"],
             [["Multi-camera edited source", "0.5 – 0.6", "Hard cuts are frequent and unambiguous; a low threshold fires on every pan and zoom instead"],
              ["Talking head, single camera", "0.35 – 0.45", "Few genuine scene changes; this range still catches cutaways and reframes"],
              ["Live event, locked-off wide shot", "0.5+, or skip it", "Almost nothing changes visually — audio energy has to carry the whole selection"],
              ["Sports, fast handheld", "0.25 – 0.35", "Motion and camera shake trigger false positives at higher thresholds, so tolerate more noise here and filter it downstream"],
              ["Screen recording, tutorial", "0.6 – 0.7", "Long static frames punctuated by real transitions; a high threshold avoids firing on cursor movement"]])),
  ("h2", "Finding highlights with audio"),
  ("p", "For unedited footage — an event, a talk, a match — the visual track is often uniform and the interesting moments are audible: a cheer, a laugh, a sudden loudness jump. Audio energy is a crude but effective highlight detector, and it is cheap to compute."),
  ("formula", "# per-window loudness, one line per measurement\nffmpeg -i input.mp4 -af ebur128=framelog=verbose -f null - 2&gt;&amp;1\n\n# volume statistics across the whole file\nffmpeg -i input.mp4 -af volumedetect -f null - 2&gt;&amp;1\n\n# detect silence, then treat the gaps between silences as segments\nffmpeg -i input.mp4 -af silencedetect=noise=-30dB:d=0.6 -f null - 2&gt;&amp;1"),
  ("p", "Two approaches that work in practice. <strong>Peak-relative:</strong> compute short-term loudness over one-second windows, then keep windows more than roughly 6 dB above the file's median — those are your spikes. <strong>Silence-inverted:</strong> use <code>silencedetect</code> to find quiet gaps, treat the audible stretches between them as natural segments, and rank those segments by mean loudness."),
  ("p", "Then pad each pick: a highlight starts before the spike. Two to three seconds of lead-in and one to two of tail turns a jarring fragment into a watchable clip."),
  ("h3", "Scoring a candidate segment: audio energy plus scene density"),
  ("p", "Once both detectors have run, every candidate window gets one number so they can be ranked against each other and against the target runtime. A simple weighted sum works well in practice, because it lets you decide up front whether cuts or loudness should dominate the ranking for this footage."),
  ("formula", "score = w_audio × normalised_audio_energy + w_scene × normalised_scene_density\n\nWorked, two 10-second candidates, w_audio = 0.6, w_scene = 0.4:\n\nSegment A: peak loudness 6 dB over median  → normalised_audio  = 0.80\n           1 scene change in the window     → density 0.10/s → normalised_scene = 0.25\n           score = 0.6(0.80) + 0.4(0.25) = 0.48 + 0.10 = 0.58\n\nSegment B: peak loudness 2 dB over median  → normalised_audio  = 0.30\n           3 scene changes in the window    → density 0.30/s → normalised_scene = 0.75\n           score = 0.6(0.30) + 0.4(0.75) = 0.18 + 0.30 = 0.48\n\nSegment A wins despite fewer cuts, because w_audio was set high on purpose:\nfor event footage, loudness is signal and rapid scene changes are usually camera shake, not content."),
  ("p", "The weights are the actual editorial decision, made explicit instead of buried in code. Event and talk footage should weight audio heavily, as above. A multi-camera edited source, where cuts were placed deliberately by a human, should weight scene density higher instead — the cut points themselves are already the signal."),
  ("h2", "Cutting without re-encoding"),
  ("p", "Stream copy is enormously faster than re-encoding, but it can only cut at keyframes. Put <code>-ss</code> before <code>-i</code> and ffmpeg seeks quickly to the nearest keyframe; put it after, and it decodes up to the exact frame, which is accurate and slow."),
  ("formula", "# fast, keyframe-aligned, no quality loss\nffmpeg -ss 00:01:12 -i input.mp4 -t 8 -c copy clip01.mp4\n\n# frame-accurate, re-encodes\nffmpeg -i input.mp4 -ss 00:01:12.400 -t 8 \\\n  -c:v libx264 -crf 18 -preset veryfast -c:a aac clip01.mp4"),
  ("p", "The pragmatic compromise: cut with stream copy when the keyframe interval is small enough that a fraction of a second of drift does not matter, and re-encode only the clips where the cut point must be exact. Or force a short keyframe interval when you control the source encode."),
  ("h3", "Keyframe interval, GOP, and a worked drift example"),
  ("p", "A GOP (group of pictures) is the span between one keyframe and the next. Frames inside it are stored as differences from nearby frames, so a decoder — and a stream-copy cut — can only start cleanly at a keyframe. A long GOP means fewer keyframes, a smaller file, and worse worst-case drift when you cut with <code>-c copy</code>."),
  ("formula", "keyframe interval = 250 frames @ 30fps = 8.33s between keyframes\ndesired cut point  = 12.40s\nnearest keyframe   = 8.33s (the one before it — copy cannot cut after it)\nstream-copy drift  = 12.40s − 8.33s = 4.07s too early\n\n# force a 1-second GOP so the worst case shrinks to well under a second\nffmpeg -i input.mp4 -c:v libx264 -g 30 -keyint_min 30 -sc_threshold 0 \\\n  -c:a aac source_tight_gop.mp4\n\n# after -g 30 (1s GOP at 30fps):\nnearest keyframe   = 12.00s\nstream-copy drift  = 12.40s − 12.00s = 0.40s, worst case ≈ 1.0s"),
  ("p", "The trade is file size: a 1-second GOP writes roughly 8 times as many full I-frames as the 250-frame default, which grows the source file noticeably. Force a tight GOP only on footage you know will be cut heavily and stream-copied, not as a universal default."),
  ("h2", "Concatenating the picks"),
  ("p", "The concat demuxer joins files without re-encoding, but only when every input shares the same codec, resolution, frame rate, and audio parameters. Mixed sources need the concat filter, which re-encodes."),
  ("formula", "# clips.txt\nfile 'clip01.mp4'\nfile 'clip02.mp4'\nfile 'clip03.mp4'\n\nffmpeg -f concat -safe 0 -i clips.txt -c copy reel.mp4"),
  ("warn", "If concatenated output plays the first clip and then freezes or desyncs, the inputs did not actually match. Normalise every clip to identical codec, resolution, frame rate, sample rate, and channel layout first, or switch to the concat filter and accept one re-encode."),
  ("h2", "Converting to 9:16 vertical"),
  ("p", "Vertical delivery from horizontal footage is a framing decision, not a resize. Three options, in ascending order of effort:"),
  ("table", (["Approach", "How it looks", "When to use it"],
             [["Blurred-background pad", "Original centred, blurred enlarged copy behind it", "Fast, safe default for talking-head and wide shots"],
              ["Centre crop", "Fills the frame, cuts off both sides", "Subject reliably centred; loses anything at the edges"],
              ["Tracked crop", "Crop window follows the subject", "Best result, needs detection per frame and real work"]])),
  ("formula", "# blurred-background 1080x1920\nffmpeg -i reel.mp4 -filter_complex \\\n \"[0:v]scale=1080:-2,boxblur=20:2,crop=1080:1920[bg];\\\n  [0:v]scale=1080:-2[fg];\\\n  [bg][fg]overlay=(W-w)/2:(H-h)/2\" \\\n -c:a copy vertical.mp4\n\n# centre crop to 9:16\nffmpeg -i reel.mp4 -vf \\\n \"crop=ih*9/16:ih,scale=1080:1920\" -c:a copy vertical.mp4"),
  ("p", "Finish with loudness normalisation so clips cut from different parts of a recording do not jump in volume. The two-pass <code>loudnorm</code> filter targeting around −14 LUFS is the usual choice for social platforms."),
  ("formula", "ffmpeg -i vertical.mp4 -af loudnorm=I=-14:TP=-1.5:LRA=11 \\\n  -c:v copy final.mp4"),
  ("h2", "Hardware acceleration, compared"),
  ("p", "The final encode is the one step in the pipeline that cannot be avoided, and it is the slowest one. Hardware encoders trade some quality-per-bit for a large speed win, which is usually the right trade while iterating and sometimes the wrong one for final delivery."),
  ("table", (["Option", "Platform", "Speed vs software x264", "Quality per bit", "Notes"],
             [["VideoToolbox", "macOS, including Apple Silicon", "Roughly 3–8x faster", "Slightly behind x264 at equal bitrate", "No setup on a Mac; the sensible default while iterating"],
              ["NVENC", "NVIDIA GPU", "Roughly 5–10x faster", "Close to x264's medium preset on recent generations", "Needs an NVIDIA GPU and current drivers"],
              ["Quick Sync (QSV)", "Intel CPU with integrated graphics", "Roughly 3–6x faster", "Historically behind x264, the gap has closed", "Free hardware most Intel laptops already have"],
              ["VA-API", "Linux, various GPUs", "Varies", "Varies by driver", "Least consistent of the options, driver-dependent"],
              ["Software libx264", "Any CPU", "Baseline", "Best quality per bit — the reference everything else is measured against", "Slowest; use it for the final export when quality matters most"]])),
  ("h2", "Encode settings: CRF, bitrate, and presets"),
  ("p", "Three settings do almost all the work of an x264 or x265 encode, and confusing them is the most common way to waste render time or ship a worse-looking file than necessary."),
  ("table", (["Setting", "What it controls", "Trade-off"],
             [["CRF (constant rate factor)", "Targets a visual quality directly; the encoder spends whatever bitrate that quality needs, scene by scene", "The right default for most delivery. Lower CRF is higher quality and a bigger file — 18 is close to lossless, 23 is a reasonable default, 28 is visibly compressed"],
              ["Target bitrate, typically 2-pass", "Targets a file size or bandwidth ceiling directly", "Use only when a platform enforces a hard cap. Quality varies scene to scene to hit the number instead of the number varying to hit quality"],
              ["Preset (ultrafast … veryslow)", "How much effort the encoder spends finding efficient encodings, at a fixed CRF", "Slower presets produce a smaller file at the same visual quality, for more CPU time. veryfast is fine for iterating; use slow or veryslow only on the final export"]])),
  ("formula", "# iterating on cuts — fast, good enough to judge the edit\nffmpeg -i joined.mp4 -c:v libx264 -crf 23 -preset veryfast -c:a aac out_draft.mp4\n\n# final delivery — slower, smaller file at equal visual quality\nffmpeg -i joined.mp4 -c:v libx264 -crf 20 -preset slow -c:a aac -b:a 192k out_final.mp4"),
  ("h2", "Putting it together: a worked end-to-end script"),
  ("p", "Every piece above is one stage. Chained, with the analysis kept cheap and the encode done exactly once at the end, the pipeline looks like this."),
  ("formula", "#!/usr/bin/env bash\nset -euo pipefail\n\nSRC=\"$1\"                       # input.mp4\nOUT=\"reel.mp4\"\nWORKDIR=$(mktemp -d)\n\n# 1. probe\nDURATION=$(ffprobe -v error -show_entries format=duration -of csv=p=0 \"$SRC\")\n\n# 2. detect scene cuts (timestamps only)\nffprobe -show_frames -of csv=p=0 \\\n  -f lavfi \"movie=$SRC,select=gt(scene\\,0.4)\" \\\n  -show_entries frame=pkt_pts_time &gt; \"$WORKDIR/scenes.txt\"\n\n# 3. detect audio spikes (silencedetect, inverted downstream)\nffmpeg -i \"$SRC\" -af silencedetect=noise=-30dB:d=0.6 -f null - 2&gt; \"$WORKDIR/silence.log\"\n\n# 4. score and select candidate segments against a target runtime\npython3 score_segments.py \"$WORKDIR/scenes.txt\" \"$WORKDIR/silence.log\" \\\n  --target-duration 90 &gt; \"$WORKDIR/picks.txt\"\n\n# 5. cut each pick, stream copy where possible\ni=0\nwhile read -r start end; do\n  i=$((i + 1))\n  ffmpeg -ss \"$start\" -i \"$SRC\" -t \"$(echo \"$end - $start\" | bc)\" \\\n    -c copy \"$WORKDIR/clip$i.mp4\"\n  echo \"file '$WORKDIR/clip$i.mp4'\" &gt;&gt; \"$WORKDIR/clips.txt\"\ndone &lt; \"$WORKDIR/picks.txt\"\n\n# 6. assemble: concat, then one encode at the end\nffmpeg -f concat -safe 0 -i \"$WORKDIR/clips.txt\" -c copy \"$WORKDIR/joined.mp4\"\nffmpeg -i \"$WORKDIR/joined.mp4\" \\\n  -af loudnorm=I=-14:TP=-1.5:LRA=11 \\\n  -c:v libx264 -crf 20 -preset slow -c:a aac \"$OUT\""),
  ("p", "The only genuinely custom piece is <code>score_segments.py</code> — the weighted-sum ranking from earlier, reading the two detector outputs and writing start and end timestamps for whichever candidates best fit the target runtime. Everything else is ffmpeg and ffprobe, called the same way a human would from a terminal."),
  ("h2", "Troubleshooting"),
  ("table", (["Symptom", "Likely cause", "Fix"],
             [["Output plays the first clip then freezes or goes black", "concat demuxer given inputs with mismatched codec, resolution, or audio parameters", "Normalise every clip to identical parameters first, or switch to the concat filter and accept one re-encode"],
              ["A -c copy cut lands noticeably off target", "Stream copy snapped to the nearest keyframe", "Re-encode just that clip, or shorten the source's GOP so the worst-case drift is smaller"],
              ["Scene detection fires constantly on a locked-off shot", "Threshold too low for low-motion footage; it is picking up compression noise", "Raise the threshold per the calibration table above, or drop scene detection and rely on audio energy instead"],
              ["Vertical crop cuts off the subject", "Centre crop assumes the subject is centred in the original frame", "Switch to the blurred-background pad, or implement a tracked crop"],
              ["Loudness jumps between clips in the final reel", "No normalisation pass, or loudnorm applied before concatenation instead of after", "Apply two-pass loudnorm as the last step, on the assembled file, not on individual clips"],
              ["Hardware-encoded output looks visibly worse than software at the same bitrate", "Hardware encoders trade quality for speed at equal bitrate", "Raise the target quality or bitrate for hardware encodes, or fall back to libx264 for the final delivery pass"],
              ["ffmpeg reports an unsafe file name on concat", "-safe 0 omitted, or clips.txt uses paths outside its own directory", "Add -safe 0, or use absolute paths consistent with where clips.txt lives"]])),
  ("h2", "Why local beats an API for this"),
  ("ul", ["<strong>No upload.</strong> A 4 GB event recording takes longer to upload on a home connection than to process locally. The transfer is the bottleneck, not the compute.",
          "<strong>No per-minute cost.</strong> Video APIs price per minute processed. Iterating on a threshold means reprocessing the same footage twenty times — free locally, expensive per call.",
          "<strong>No rights question.</strong> Footage of identifiable people at an event does not go to a third party at all, which removes both a consent conversation and a terms-of-service question about training use.",
          "<strong>Deterministic and debuggable.</strong> The same command produces the same output, and every intermediate is a file you can open.",
          "<strong>No dependency on someone else's uptime or pricing page.</strong> The pipeline works the same in three years."]),
  ("p", 'The honest counterpoint: an API gives you transcription, face tracking, and semantic highlight selection that a local ffmpeg pipeline does not have without extra models. If your selection logic genuinely needs to understand speech, run a local transcription model — the same local-over-API case, made generally, is in <a href="/guides/local-llm-ollama.html">the local LLM guide</a> — and keep the rest of the pipeline where it is.'),
  ("p", 'This is the architecture behind <a href="/eventreels.html">EventReels</a> — probe, detect, score, cut, assemble, one encode at the end, entirely on the machine, on the same <a href="/stack.html">stack</a> the rest of this site runs on. It is the same no-third-party argument made more generally in <a href="/guides/client-side-only-tools.html">the client-side tools guide</a>, applied here to gigabytes of footage instead of a few kilobytes of JSON, and it slots into a broader shop workflow the way <a href="/guides/ai-automation-small-business.html">the automation guide</a> describes.'),
 ],
 "tools": [("/eventreels.html", "EventReels", "the working auto-editing pipeline this guide describes."),
           ("/stack.html", "My stack", "the rest of the tooling around it."),
           ("/guides/local-llm-ollama.html", "Local LLM guide", "the same local-over-API argument applied to language models."),
           ("/guides/ai-automation-small-business.html", "AI automation guide", "where a pipeline like this fits into an actual workflow.")],
 "faqs": [
  ("How do you detect scene changes with ffmpeg?", "Use the select filter's scene score, which rates how different each frame is from the previous one on a 0 to 1 scale, and threshold it — for example select='gt(scene,0.4)'. Around 0.3 is sensitive and fires on camera movement, 0.4 is a reasonable default, and 0.5 or above catches hard cuts only."),
  ("How do you find highlights in a video automatically?", "Analyse audio energy rather than video. Compute short-term loudness with the ebur128 filter and keep windows several decibels above the file's median, or use silencedetect to find quiet gaps and rank the audible segments between them by mean loudness. Pad each pick with a few seconds of lead-in."),
  ("How do you cut a video without re-encoding?", "Use -c copy for stream copy, with -ss placed before -i so ffmpeg seeks quickly. The limitation is that stream copy can only cut at keyframes, so the cut point may drift by a fraction of a second; put -ss after -i and re-encode when the cut must be frame-accurate."),
  ("Why does concatenated ffmpeg output freeze or desync?", "The concat demuxer with -c copy requires every input to share the same codec, resolution, frame rate, sample rate, and channel layout. When they differ, playback typically works for the first clip then breaks. Normalise all clips to identical parameters first, or use the concat filter and accept one re-encode."),
  ("How do you convert horizontal video to 9:16 vertical?", "Three options: pad with a blurred, enlarged copy of the video behind the original, which is the safe default; centre-crop to ih*9/16 by ih and scale to 1080x1920, which fills the frame but loses the edges; or track the subject and move the crop window, which looks best but requires per-frame detection."),
  ("Why use a local ffmpeg pipeline instead of a video API?", "No upload time on large files, no per-minute processing cost while you iterate on thresholds, no third party receiving footage of identifiable people, deterministic output you can debug file by file, and no exposure to another company's pricing or uptime. The trade is that APIs bundle transcription and face tracking that ffmpeg alone does not provide."),
  ("What scene-detection threshold should I use in ffmpeg?", "It depends on the footage, not a fixed constant. Multi-camera edited sources want 0.5 to 0.6 since cuts are frequent and unambiguous; a single-camera talking head wants 0.35 to 0.45; fast handheld or sports footage wants 0.25 to 0.35 to tolerate camera-shake noise; and a locked-off wide shot at an event should mostly rely on audio energy instead, since almost nothing changes visually."),
  ("What CRF value should I use when encoding with ffmpeg?", "CRF 23 is a reasonable default for libx264, with 18 close to lossless and 28 visibly compressed. Pair a low CRF like 20 with a slow preset for final delivery, where the encoder spends more time finding an efficient encoding, and use a fast CRF-23 pass with the veryfast preset while iterating on cuts, since encode time matters more than file size at that stage."),
 ],
},

{
 "slug": "print-on-demand-economics",
 "title": "Print-on-Demand Margin Math, Honestly",
 "desc": "Base cost, retail, platform fees, and net per unit on a tee and a hoodie — plus the costs people forget: returns, samples, artwork time, and ads.",
 "og_title": "Print-on-Demand Margin Math, Honestly",
 "og_desc": "A worked net-per-unit table on a tee and a hoodie, and the costs that quietly eat the margin.",
 "headline": "Print-on-Demand Margin Math, Honestly",
 "crumb": "Print-on-Demand Math",
 "about": ["Print on demand", "Unit economics", "Ecommerce"],
 "eyebrow": "Guide · Business",
 "h1": "The margin is fine. The volume is the problem.",
 "lead": "Print-on-demand removes inventory risk, which is the thing that kills most clothing brands. What it does not remove is the arithmetic: a good margin on a product nobody has heard of still earns nothing.",
 "type": "Article",
 "nav": NAV_BRAND,
 "body": [
  ("callout", "Every figure below is an <strong>illustrative example of the arithmetic</strong>, chosen to be realistic in shape. They are not quotes from any specific supplier and they are not results from any brand. Suppliers price differently by garment, print area, colour count, and region — run your own numbers against a real quote before deciding anything."),
  ("h2", "The three numbers"),
  ("p", "Print-on-demand economics reduce to base cost, retail price, and platform fee. Everything else is a variation on those three."),
  ("ul", ["<strong>Base cost</strong> — what the supplier charges to print and ship one unit. Rises with garment quality, print area, number of print locations, and colour count.",
          "<strong>Retail price</strong> — what you charge. The only lever you fully control, and the one most people set too low out of nerves.",
          "<strong>Platform fee</strong> — the storefront's cut plus payment processing. Typically a percentage plus a fixed per-transaction charge."]),
  ("formula", "net per unit = retail − base cost − platform fee\n\nplatform fee ≈ (retail × fee rate) + fixed transaction charge"),
  ("h2", "A worked example on a tee"),
  ("p", "Illustrative numbers: a mid-weight tee with a single front print, retailing at $32, on a storefront taking 5% plus roughly 3% payment processing and $0.30 per transaction."),
  ("table", (["Line", "Amount", "Note"],
             [["Retail", "$32.00", "Customer pays this plus shipping"],
              ["Base cost (print + fulfilment)", "−$13.30", "Garment, print, pick and pack"],
              ["Platform + processing (~8%)", "−$2.56", "Illustrative blended rate"],
              ["Fixed transaction fee", "−$0.30", "Per order, not per item"],
              ["<strong>Net per unit</strong>", "<strong>$15.84</strong>", "About 49% of retail"]])),
  ("h2", "The same math on a hoodie"),
  ("p", "Hoodies carry a much higher base cost, so the percentage margin compresses even though the dollar margin grows."),
  ("table", (["Line", "Amount", "Note"],
             [["Retail", "$58.00", ""],
              ["Base cost", "−$19.20", "Heavier garment, larger print area"],
              ["Platform + processing (~8%)", "−$4.64", ""],
              ["Fixed transaction fee", "−$0.30", ""],
              ["<strong>Net per unit</strong>", "<strong>$33.86</strong>", "About 58% of retail"]])),
  ("p", "Read those two tables together and the first real lesson appears: <strong>the hoodie earns more than twice the dollars per sale</strong>, which matters far more than the percentage. Percentages do not pay rent; dollars per order do. This is why brands push toward higher-ticket items and multi-item carts rather than optimising a tee's margin by a point."),
  ("h2", "The volume problem"),
  ("p", "$15.84 a shirt sounds fine until you multiply it."),
  ("table", (["Units sold / month", "Gross margin at $15.84", "What that actually is"],
             [["10", "$158", "A hobby"],
              ["50", "$792", "A meaningful side income"],
              ["200", "$3,168", "A part-time job with real operational load"],
              ["1,000", "$15,840", "A business, with staffing and support needs"]])),
  ("p", "Selling 200 shirts a month is not a design problem. It is a distribution problem — audience, content cadence, repeat customers, and retention. <strong>Print-on-demand solves inventory risk and solves nothing about demand,</strong> and demand is the part that is genuinely hard. The people who quit usually quit with a good product and no traffic."),
  ("h2", "The costs nobody puts in the spreadsheet"),
  ("table", (["Hidden cost", "Typical shape", "Effect on net"],
             [["Returns and reprints", "A few percent of orders, often on you rather than the supplier", "Shaves a few percent off net across all units"],
              ["Samples", "One unit of each product, at your own cost, plus shipping", "A fixed upfront spend before any revenue exists"],
              ["Artwork time", "Hours per design, plus mockups and revisions", "Free only if your time is worthless"],
              ["Ads", "Cost per acquisition frequently exceeds net per unit on a single item", "Can turn a positive-margin product into a loss"],
              ["Shipping expectations", "Customers expect free or cheap shipping", "Either raise retail or absorb it out of net"],
              ["Payment disputes", "Chargebacks carry the refund plus a fixed fee", "Small in volume, painful per event"],
              ["Platform changes", "Base costs and fee rates get revised", "Your margin is quietly repriced by someone else"]])),
  ("p", "The one that ends most stores is the ads line. If net per unit is $15.84 and it costs $22 in ads to acquire a customer who buys one item, every sale loses money — and that only becomes visible after you have spent enough to see it. The escape routes are higher average order value, repeat purchases, or acquisition that does not cost money per unit, which is what organic content actually is."),
  ("h2", "Fixed costs and the break-even count"),
  ("p", "Net per unit is a contribution margin, not a profit — it still has to cover whatever runs whether or not a single unit sells. As an illustrative example, call the fixed monthly cost of running a small store $85: a storefront subscription, a design tool, a domain. Divide that by the contribution margin per unit and the break-even count falls out as arithmetic, not a guess."),
  ("formula", "break-even units = fixed costs ÷ contribution margin per unit\n\nIllustrative: $85 fixed cost ÷ $15.84 net per tee ≈ 5.4 → 6 tees a month\njust to cover the fixed line, before a dollar of profit exists"),
  ("p", "Six units a month is a low bar, which is the point of the exercise — the fixed costs of a print-on-demand store are genuinely small. The number that matters is not whether you clear break-even, it is how far past it the volume table further down actually gets you, because everything past unit six is where the business starts."),
  ("h2", "Average order value and the fixed per-order fee"),
  ("p", "The most common argument for chasing a bigger cart is the fixed per-order fee. It is real, and it is smaller than people assume — worth sizing before treating it as the whole case for average order value."),
  ("table", (["Cart", "Illustrative revenue", "Fixed fee as share of revenue", "What changes"],
             [["1 item", "$32", "$0.30 ÷ $32 = 0.9%", "Baseline"],
              ["2 items, one order", "$64", "$0.30 ÷ $64 = 0.5%", "Fee's share of revenue roughly halves"],
              ["4 items, one order", "$128", "$0.30 ÷ $128 = 0.2%", "Fee is nearly invisible"],
              ["Same 4 items, four separate orders", "$128", "$1.20 total ÷ $128 = 0.9%", "Four times the fixed-fee drag of a single order"]])),
  ("p", 'The saving is real and it shrinks fast as cart size grows — the fixed fee stops mattering well before it stops existing. What a bigger cart genuinely buys is one shipment, one acquisition cost, and one support thread instead of several, which matters far more than the $0.30. The line-by-line version of this argument, worked against real garment costs, is in the companion guide: <a href="/guides/clothing-brand-pod-margins.html">Print-on-Demand Margins for a Clothing Brand</a>.'),
  ("h2", "Customer acquisition cost against lifetime value"),
  ("p", "Net per unit means nothing next to what it costs to bring the customer in. As an illustrative example: if a paid channel costs $18 to acquire one new customer, and that customer's first order nets $15.84, the first sale is a loss before the arithmetic even reaches product cost."),
  ("formula", "illustrative lifetime contribution = (orders × net per order) − acquisition cost\n\n1 order over the relationship:  $15.84 × 1 − $18 = −$2.16   (a loss)\n2 orders over the relationship: $15.84 × 2 − $18 = $13.68\n4 orders over the relationship: $15.84 × 4 − $18 = $45.36"),
  ("p", 'The arithmetic says what every paid-acquisition channel eventually teaches the hard way: a positive-margin product financed by ads is a bet on repeat behaviour, not on the first sale. If repeat rate is unknown, plan on the pessimistic case — one order per customer — because that is the scenario where the loss actually shows up, and it is the one worth being able to survive. Getting the traffic to convert at all before any of this math applies is <a href="/guides/landing-page-that-converts.html">a separate problem</a>.'),
  ("h2", "Returns-rate sensitivity"),
  ("p", "Illustratively, a returned tee forfeits the $13.30 base cost plus roughly $4.50 of outbound shipping that is rarely recovered, for about $17.80 lost per return. Modelled as a tax across 100 orders rather than a rare event, the effect on net compounds quickly."),
  ("table", (["Return rate", "Effective net per unit", "Change from 0%"],
             [["0%", "$15.84", "—"],
              ["3%", "$14.83", "−6.4%"],
              ["5%", "$14.16", "−10.6%"],
              ["10%", "$12.48", "−21.2%"],
              ["20%", "$9.11", "−42.5%"]])),
  ("p", "At a 20% return rate, illustratively, the product has lost more than two-fifths of its margin without a single change to price or ad spend. Return rate is not a rounding error in this model, it is a lever roughly as strong as the ad-cost line above."),
  ("h3", "International shipping and duties"),
  ("p", "Cross-border orders add a variable that a domestic-only calculation ignores until the first angry email arrives about a customs bill. A few structural points, without inventing a specific country's rate, which changes too often to state as fact here:"),
  ("ul", ["<strong>DDU versus DDP.</strong> Delivered-duty-unpaid means the customer is billed duty on arrival, often as a surprise; delivered-duty-paid folds it into checkout. DDP converts better and is worth the platform fee where it is offered.",
          "<strong>A regional print network reduces both problems at once.</strong> Fulfilling from a facility inside the destination country or trade bloc cuts shipping time and frequently keeps the order under a duty-free threshold that a shipment from outside would not clear.",
          "<strong>VAT registration is a separate obligation from platform fees.</strong> Selling into the EU or UK past certain thresholds can require VAT registration regardless of what the fulfilment platform already collects.",
          "<strong>State the policy before checkout, not after.</strong> A customer who discovers a duty charge at their door writes an angry review; a customer who saw it as an estimate at checkout does not."]),
  ("h2", "A pricing ladder"),
  ("p", "Illustratively, a small line reads better as a ladder than as a single price, because dollars per order — not percentage margin — is what pays rent, and a ladder gives a customer more than one dollar amount to say yes to."),
  ("table", (["Tier", "Illustrative retail", "Role", "Illustrative net"],
             [["Low-friction entry (sticker, pin, small accessory)", "$8–$12", "List-building and a low-risk first purchase", "A few dollars; the email address is the actual return"],
              ["Core hero item (tee)", "$32", "Most listings, most traffic", "$15.84, per the worked table above"],
              ["Step-up item (long sleeve, crewneck)", "$38–$44", "Bridges tee and hoodie without the full hoodie cost", "Illustratively between the two, closer to the hoodie's percentage"],
              ["Flagship (hoodie)", "$58", "Highest dollar margin, the seasonal push item", "$33.86, per the worked table above"],
              ["Bundle (two core items, one order)", "Sum of components, minus a small discount", "Raises AOV, spreads one fixed fee across two units", "Roughly the sum of two margins, minus whatever discount was given"]])),
  ("p", 'None of this is a menu to copy. It is the shape a ladder takes once dollars per order is accepted as the real metric — a low-margin entry item earns its keep by building the list and the repeat-purchase pool the CAC-versus-lifetime-value math above depends on, not by profit on its own. The same ladder logic, at zero marginal cost instead of a garment cost, is worked out for digital goods in <a href="/guides/pricing-a-digital-product.html">the digital product pricing guide</a>, and the finished version of both sits in <a href="/store.html">the store</a>.'),
  ("h2", "Pricing, briefly"),
  ("ol", ["<strong>Start from the net you need,</strong> not from what competitors charge. Work backwards to retail.",
          "<strong>Price the bundle, not the item.</strong> The fixed transaction fee is per order, so a two-item cart is structurally more profitable.",
          "<strong>Do not compete on price against a supplier that has scale you do not.</strong> You will lose, and you will lose on your own margin.",
          "<strong>Recheck after every supplier price change.</strong> Base costs move; retail prices usually do not until someone notices.",
          "<strong>Treat free shipping as a price increase,</strong> because it is one. Fold it into retail deliberately rather than absorbing it silently."]),
  ("h2", "Why print-on-demand is still the right start"),
  ("p", "Held against the alternative, the case is strong. Bulk ordering 200 units means several thousand dollars committed before a single customer exists, a size curve guessed in advance, and boxes in a room. Print-on-demand trades roughly a third of the per-unit margin for zero inventory risk, no minimum order, and the ability to kill a design that does not sell without eating the stock."),
  ("p", 'For testing whether a design has an audience at all, that trade is clearly correct. Move to bulk only once a specific item has demonstrated repeat demand — and at that point the higher margin is earned by evidence rather than assumed. This is the model behind <a href="/kxngsef.html">KXNG SEF</a> and <a href="/heft.html">HEFT</a>: no inventory, no minimums, designs that do not sell simply stop being printed.'),
 ],
 "tools": [("/kxngsef.html", "KXNG SEF", "clothing brand run on a print-on-demand model."),
           ("/heft.html", "HEFT", "second brand on the same fulfilment model."),
           ("/store.html", "Store", "the digital-product side, where the unit economics work very differently."),
           ("/guides/ai-automation-small-business.html", "AI automation guide", "reducing the per-order operational load.")],
 "faqs": [
  ("How do you calculate print-on-demand profit per unit?", "Net per unit equals retail price minus base cost minus platform fees, where platform fees are usually a percentage of retail plus a fixed per-transaction charge. As an illustrative example, a $32 tee with a $13.30 base cost and roughly 8% plus $0.30 in fees nets about $15.84."),
  ("What margin is realistic on print-on-demand?", "Illustratively, around 45 to 60% of retail once base cost and platform fees are removed, with hoodies typically showing a higher percentage and a much higher dollar margin than tees. Actual figures depend entirely on your supplier, garment, print area, and storefront, so run the numbers against a real quote."),
  ("Is print-on-demand profitable?", "Per unit, usually yes. In total, only at volume — an illustrative $15.84 net per shirt means 10 sales a month is a hobby and 200 is a part-time job. Print-on-demand removes inventory risk but does nothing about demand, which is the genuinely hard part."),
  ("What costs do print-on-demand sellers forget?", "Returns and reprints, samples bought at your own cost, the hours spent on artwork and mockups, shipping that customers expect to be free, chargebacks, and above all advertising. Ad cost per acquisition frequently exceeds net per unit on a single item, which turns a profitable product into a loss."),
  ("Should you sell tees or hoodies?", "Hoodies carry a higher base cost but a much larger dollar margin per sale — illustratively about $33.86 against $15.84. Since the fixed transaction fee is charged per order rather than per item, higher-ticket products and multi-item carts are structurally more profitable than optimising a tee's margin."),
  ("Is print-on-demand better than bulk ordering?", "For starting out, yes. Bulk ordering commits thousands of dollars and a guessed size curve before any customer exists. Print-on-demand gives up roughly a third of the per-unit margin in exchange for zero inventory risk and no minimum order, which is the right trade until a specific design has proven repeat demand."),
  ("What is the break-even point for a print-on-demand store?", "Divide the fixed monthly cost of running the store by the contribution margin per unit. Illustratively, an $85 monthly fixed cost against a $15.84 net-per-tee margin breaks even at about six units a month, before any profit exists. The fixed-cost side of print-on-demand is genuinely small, which is why the volume table matters more than the break-even count itself."),
  ("Does customer acquisition cost matter more than product margin?", "Often, yes. Illustratively, an $18 cost to acquire a customer against a $15.84 net per first order is already a loss before product cost is the issue, and it only turns profitable once that customer returns. Plan on the pessimistic case of one order per customer, because that is the scenario where the loss actually shows up and the one a store needs to survive."),
 ],
},

{
 "slug": "ai-search-optimization",
 "title": "How to Get Cited by AI Answer Engines (GEO/AEO)",
 "desc": "Entity consolidation, llms.txt, robots.txt rules for named AI crawlers, FAQPage that mirrors visible text, answer-first writing, and IndexNow for fast recrawl.",
 "og_title": "How to Get Cited by AI Answer Engines",
 "og_desc": "Entity consolidation, llms.txt, AI crawler rules, mirrored FAQPage schema, and answer-first structure.",
 "headline": "How to Get Cited by AI Answer Engines: Entities, llms.txt, and Structure",
 "crumb": "AI Search Optimization",
 "about": ["Generative engine optimization", "Structured data", "Technical SEO"],
 "eyebrow": "Guide · SEO",
 "h1": "Getting cited when the answer replaces the click",
 "lead": "Ranking and being cited are now different problems. An answer engine reads a handful of sources, decides which ones are unambiguous enough to quote, and names those. Being quotable is a structural property, and it is one you can engineer.",
 "level": "Intermediate",
 "nav": NAV_DEV,
 "body": [
  ("h2", "What changed"),
  ("p", "Classic SEO optimised for a ranked list of ten links. AI answer engines — ChatGPT search, Perplexity, Copilot, Google's AI overviews, Claude's web search — synthesise a single answer from a few retrieved sources and cite some of them. That shifts the target from <em>rank higher</em> to <strong>be the passage a model can lift verbatim and attribute confidently.</strong>"),
  ("p", "The practices go by two names: <strong>GEO</strong> (generative engine optimization) and <strong>AEO</strong> (answer engine optimization). They overlap almost entirely, and neither requires abandoning normal SEO — a page that is crawlable, fast, and structured still wins both. What changes is the emphasis: unambiguous entities, self-contained passages, and machine-readable facts."),
  ("h2", "Entity consolidation: one @id, referenced everywhere"),
  ("p", "The single highest-leverage technical move is making a retrieval system certain <em>who</em> the site is about. If ten pages each declare a separate Person node, a model sees ten weakly-connected entities. If ten pages reference one canonical <code>@id</code>, it sees one entity with ten pieces of evidence."),
  ("formula", "// on the homepage only — the canonical definition\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Person\",\n  \"@id\": \"https://example.com/#person\",\n  \"name\": \"Full Name\",\n  \"url\": \"https://example.com/\",\n  \"jobTitle\": \"...\",\n  \"knowsAbout\": [\"...\", \"...\"],\n  \"sameAs\": [\n    \"https://github.com/handle\",\n    \"https://www.linkedin.com/in/handle\",\n    \"https://orcid.org/0000-...\"\n  ]\n}\n\n// on every other page — reference, never redefine\n\"author\":    {\"@id\": \"https://example.com/#person\"},\n\"publisher\": {\"@id\": \"https://example.com/#person\"}"),
  ("ul", ["<strong>Define once, reference everywhere.</strong> Re-stating the full Person object on every page invites contradictions, and contradictions are what make a model hedge instead of cite.",
          "<strong><code>sameAs</code> is the disambiguation lever.</strong> Link the profiles that already have independent authority — GitHub, LinkedIn, ORCID, a publisher DOI page. This is how an entity gets tied to an existing graph rather than floating alone.",
          "<strong>Keep names byte-identical</strong> across schema, page text, and external profiles. 'J. Smith' in one place and 'John Smith' in another is two entities as far as a matcher is concerned.",
          "<strong>Use <code>knowsAbout</code> deliberately.</strong> It is a direct statement of topical scope, and it is one of the few places you get to declare it rather than have it inferred.",
          "<strong>Validate every deploy.</strong> A JSON-LD syntax error means the block is skipped entirely and silently."]),
  ("h3", "A small entity graph, worked"),
  ("p", "One entity rarely stands alone. A realistic graph links the person, the site, and each piece of content with <code>@id</code> references, so a retrieval system can walk from an article to its author to the rest of their work in a single hop instead of guessing at the connection."),
  ("formula", "{\n  \"@context\": \"https://schema.org\",\n  \"@graph\": [\n    {\n      \"@type\": \"Person\",\n      \"@id\": \"https://example.com/#person\",\n      \"name\": \"Full Name\",\n      \"url\": \"https://example.com/\",\n      \"sameAs\": [\"https://github.com/handle\", \"https://www.linkedin.com/in/handle\"]\n    },\n    {\n      \"@type\": \"WebSite\",\n      \"@id\": \"https://example.com/#website\",\n      \"url\": \"https://example.com/\",\n      \"name\": \"Site Name\",\n      \"publisher\": {\"@id\": \"https://example.com/#person\"}\n    },\n    {\n      \"@type\": \"TechArticle\",\n      \"@id\": \"https://example.com/guides/example.html#article\",\n      \"headline\": \"Example Guide\",\n      \"url\": \"https://example.com/guides/example.html\",\n      \"author\": {\"@id\": \"https://example.com/#person\"},\n      \"publisher\": {\"@id\": \"https://example.com/#person\"},\n      \"isPartOf\": {\"@id\": \"https://example.com/#website\"}\n    },\n    {\n      \"@type\": \"BreadcrumbList\",\n      \"@id\": \"https://example.com/guides/example.html#breadcrumb\",\n      \"itemListElement\": [\n        {\"@type\": \"ListItem\", \"position\": 1, \"name\": \"Guides\", \"item\": \"https://example.com/guides.html\"},\n        {\"@type\": \"ListItem\", \"position\": 2, \"name\": \"Example Guide\"}\n      ]\n    }\n  ]\n}"),
  ("p", "Four <code>@id</code> values, four cross-references, zero duplicated definitions. Every subsequent article on the site adds one more <code>TechArticle</code> node pointing at the same two <code>@id</code> values — the graph gets denser with every page published instead of wider with every page repeating itself."),
  ("h3", "Which schema type for which page"),
  ("p", "Not every page needs the same markup, and forcing one type onto a page it does not describe is as unhelpful to a model as having none."),
  ("table", (["Page type", "Primary schema type", "Notes"],
             [["Homepage or about page", "Person or Organization", "The canonical node, defined once, referenced from every other page's author/publisher"],
              ["Guide or long-form article", "TechArticle or Article", "author and publisher point at the canonical @id, never a redefinition"],
              ["FAQ section on a guide", "FAQPage", "Must mirror the visible text exactly — the rule this guide keeps returning to"],
              ["Product or store listing", "Product, with an Offer", "Price and availability only if genuinely accurate; do not mark up placeholders"],
              ["App page", "SoftwareApplication", "applicationCategory and operatingSystem where they are actually true"],
              ["Any page below the root", "BreadcrumbList", "Cheap to add and a directly supported rich result on its own"],
              ["Site-wide", "WebSite", "Ties every page's schema back to the same publisher @id"]])),
  ("p", 'JSON-LD is, in effect, structured output aimed at a machine reader instead of a human one — the same discipline of naming fields precisely and never improvising a shape covered generally in <a href="/guides/structured-llm-output.html">the structured LLM output guide</a>.'),
  ("h2", "llms.txt and llms-full.txt"),
  ("p", "<code>llms.txt</code> is a proposed convention: a markdown file at the site root that gives a language model a clean, navigable summary of the site without HTML, navigation, or scripts. <code>llms-full.txt</code> is the expanded version containing the actual content."),
  ("formula", "# Site Name\n\n&gt; One-sentence description of who this is and what the site covers.\n\n## Guides\n- [Offline PWA](https://example.com/guides/offline-pwa.html): building an\n  installable offline app with no backend.\n- [RAG explained](https://example.com/guides/rag-explained.html): chunking,\n  embeddings, reranking, and where pipelines fail.\n\n## Projects\n- [Project name](https://example.com/project.html): what it does, in one line.\n\n## Contact\n- email@example.com"),
  ("p", "Two honest caveats. First, adoption is not universal — no major crawler has committed to it as a requirement, so treat it as cheap insurance rather than a guaranteed channel. Second, it is <strong>not a place to say something different from the site.</strong> Contradiction between llms.txt and the rendered pages is worse than having no file, because it introduces exactly the ambiguity you are trying to eliminate."),
  ("p", "The reason to ship it anyway: it costs an hour, it is trivially machine-parseable, and it forces you to write a clean one-line description of every page — which is useful regardless of who reads it."),
  ("h2", "robots.txt and the named AI crawlers"),
  ("p", "AI companies operate separately-named agents, often splitting training crawlers from live-retrieval crawlers. Those are different decisions: blocking training while allowing retrieval is a coherent position, and so is the reverse."),
  ("table", (["Agent", "Operator", "Primary purpose"],
             [["GPTBot", "OpenAI", "Training data collection"],
              ["OAI-SearchBot", "OpenAI", "Live search retrieval and citation"],
              ["ChatGPT-User", "OpenAI", "Fetches a page a user asked about"],
              ["ClaudeBot", "Anthropic", "Crawling for model training"],
              ["Claude-User / Claude-SearchBot", "Anthropic", "User-initiated fetch and search indexing"],
              ["PerplexityBot", "Perplexity", "Search index used for cited answers"],
              ["Google-Extended", "Google", "Controls Gemini training use; does not affect Search ranking"],
              ["Applebot-Extended", "Apple", "Controls Apple Intelligence training use"],
              ["Bingbot", "Microsoft", "Bing index, which also feeds Copilot"],
              ["CCBot", "Common Crawl", "Open crawl corpus used by many trainers"]])),
  ("formula", "User-agent: GPTBot\nAllow: /\n\nUser-agent: OAI-SearchBot\nAllow: /\n\nUser-agent: ClaudeBot\nAllow: /\n\nUser-agent: PerplexityBot\nAllow: /\n\nUser-agent: Google-Extended\nAllow: /\n\nUser-agent: Applebot-Extended\nAllow: /\n\nSitemap: https://example.com/sitemap.xml"),
  ("warn", "Blocking <code>Google-Extended</code> does not remove you from Google Search, and blocking a training crawler does not remove you from that company's live search results — the agents are separate. Equally, if you want to be cited, blocking the retrieval bots guarantees you will not be. Decide training and retrieval independently, and know which name controls which."),
  ("p", "<code>robots.txt</code> is a request, not enforcement. Crawlers that ignore it will ignore it. If content genuinely must not be read, it needs authentication, not a directive."),
  ("h3", "A crawler-policy decision matrix"),
  ("p", "Training and retrieval are two independent decisions, and stating both explicitly beats leaving either to a bot's default behaviour."),
  ("table", (["", "Retrieve: allow", "Retrieve: block"],
             [["Train: allow", "Maximum reach. Allow GPTBot, ClaudeBot, Google-Extended, Applebot-Extended, and CCBot alongside OAI-SearchBot, Claude-SearchBot, PerplexityBot, and Bingbot. No control over how the content is used later.", "Rare and usually accidental. Content feeds training runs but nothing user-initiated fetches it live, which is an odd split since the same company typically operates both agents."],
              ["Train: block", "The common, defensible middle position. Block GPTBot, ClaudeBot, Google-Extended, Applebot-Extended, and CCBot; allow OAI-SearchBot, Claude-SearchBot, PerplexityBot, and Bingbot. Keeps content out of future model weights while staying citable today.", "Full opt-out. Block every named agent. The content will not be cited by any of them and will not train anything — the cost is accepting zero AI-search-referred traffic."]])),
  ("p", 'The static-hosting case for staying retrievable while limiting training is made at more length in <a href="/guides/static-site-ai-search.html">the static-site AI search guide</a>, which covers the same crawler list from the hosting side rather than the schema side.'),
  ("h2", "FAQPage schema — and the rule that breaks sites"),
  ("p", "FAQPage markup is well-suited to answer engines: it is a list of question-answer pairs in exactly the shape a retrieval system wants. There is one hard rule."),
  ("warn", "<strong>Every question and answer in FAQPage markup must appear as visible text on the same page.</strong> Schema-only FAQ content — questions that exist in the JSON-LD but not on screen — violates Google's structured data guidelines and is a well-known cause of manual actions. Generate the visible FAQ and the schema from the same source so they cannot drift."),
  ("ul", ["Write answers that stand alone. 'It depends on the above' is unquotable; a model lifting that sentence out of context produces nothing useful.",
          "Two to four sentences per answer. Long enough to be complete, short enough to be lifted whole.",
          "Answer in the first sentence, then qualify. Never build to the answer.",
          "Use the question form a person would actually type or say, not a keyword-stuffed variant.",
          "Do not mark up promotional copy as an FAQ. It is the most common misuse and it does not survive review."]),
  ("h2", "Answer-first writing and question-shaped headings"),
  ("p", "Retrieval works on passages, not pages. A model chunks your page, embeds the chunks, and pulls the ones that match the query. That has direct consequences for structure."),
  ("ol", ["<strong>Make headings questions</strong> where it is natural — 'How do you detect scene changes?' rather than 'Detection'. The heading is often the strongest signal for what the chunk beneath it answers.",
          "<strong>Answer in the first sentence under the heading.</strong> A paragraph that spends three sentences setting up context gets chunked away from its own conclusion.",
          "<strong>Make each section self-contained.</strong> Assume the reader has only that chunk, because the model might.",
          "<strong>Use tables and lists for comparisons.</strong> They survive chunking better than prose and are easier to extract cleanly.",
          "<strong>Put specifics in the text.</strong> Numbers, versions, exact command names, and dates are what makes a passage worth citing over a generic competitor.",
          "<strong>State facts plainly and once.</strong> Hedged, repetitive prose gives a model nothing crisp to quote."]),
  ("p", "The underlying test is simple: <strong>if someone pasted one section of your page into a chat with no other context, would it answer the question?</strong> If not, that section will not get cited."),
  ("h3", "Chunking, worked: a bad section versus a good one"),
  ("p", 'Retrieval systems generally split pages into passages by heading boundary or by a fixed token window, embed each passage, and rank passages against the query — the mechanics are covered fully in <a href="/guides/rag-explained.html">the RAG explained guide</a> and <a href="/guides/embedding-model-rag.html">the embedding model guide</a>. What that means for writing is concrete enough to show side by side.'),
  ("formula", "BAD — the answer is buried past the likely chunk boundary:\n\n\"## Detection\nThere are many ways to think about how a system might notice change\nin a video, and the right approach depends a lot on the footage, but\ngenerally speaking one method that has proven useful over time involves\ncomparing consecutive frames using some kind of scoring function, which\nis roughly what happens here, tuned per source.\"\n\nGOOD — the answer is the first sentence, the heading is the query:\n\n\"## How do you detect scene changes with ffmpeg?\nThreshold the select filter's per-frame scene score on a 0 to 1 scale:\nselect='gt(scene,0.4)'. 0.3 is sensitive and fires on camera movement;\n0.5 or above catches hard cuts only.\""),
  ("p", "A fixed-size chunker slicing the bad version at roughly 40 words is likely to split before the method is ever named, producing a retrievable passage that says footage varies and approaches must be tuned — true, and useless to quote. The good version fits inside almost any chunk size whole, names the method in the first sentence, and answers the literal query in the heading before the passage is even embedded. Nothing about the underlying facts changed between the two versions — only the order they are said in."),
  ("h2", "IndexNow for fast recrawl"),
  ("p", "IndexNow is a protocol supported by Bing, Yandex, Seznam and others that lets you push URLs the moment they change instead of waiting for a crawl. That matters for AI search because Copilot is built on the Bing index — faster Bing recrawl means faster Copilot freshness."),
  ("formula", "# 1. host a key file at the site root\n#    https://example.com/&lt;key&gt;.txt  containing exactly &lt;key&gt;\n\n# 2. ping on publish\ncurl \"https://api.indexnow.org/indexnow?url=https://example.com/guides/new.html&amp;key=&lt;key&gt;\"\n\n# or submit a batch\ncurl -X POST https://api.indexnow.org/indexnow \\\n  -H \"Content-Type: application/json\" -d '{\n    \"host\": \"example.com\",\n    \"key\": \"&lt;key&gt;\",\n    \"keyList\": [\"https://example.com/guides/new.html\"]\n  }'"),
  ("p", "Google does not participate in IndexNow; for Google, keep the sitemap current and submit it in Search Console. Do not spam either — pinging unchanged URLs repeatedly is the fastest way to have the signal ignored."),
  ("h2", "How to actually tell whether you are being cited"),
  ("p", "This is the honest weak point of the whole practice: there is no unified citations dashboard across providers, so measurement is assembled from partial signals rather than read off one report."),
  ("ul", ["<strong>Ask directly.</strong> Query ChatGPT search, Perplexity, and Claude's web search with questions your pages actually answer, and check whether your domain appears in the cited sources. Crude, but it is the most direct signal available.",
          "<strong>Watch server logs for the named retrieval agents,</strong> not the training ones — OAI-SearchBot, Claude-SearchBot, PerplexityBot, Bingbot. A hit proves the page was fetched for a live query, though not that it was ultimately quoted.",
          "<strong>Check referrer strings in analytics,</strong> though treat this as a lower bound. Many AI-answer clickthroughs arrive with no referrer at all, so an undercount here does not mean zero citations.",
          "<strong>Watch for a traffic pattern with no obvious search-ranking cause</strong> — a spike in direct or referrer-less traffic to one specific page is a common fingerprint of an answer engine sending readers to the source.",
          "<strong>Use Bing Webmaster Tools alongside Google Search Console.</strong> Copilot runs on the Bing index, so Bing-side indexing status is a real proxy signal that Search Console alone will not show."]),
  ("p", "None of this is precise, and providers change what they surface without notice. Treat citation tracking the way you would treat any early-stage measurement problem: directionally useful, not a number to optimise to the decimal."),
  ("h2", "A pre-publish validation checklist"),
  ("p", "The site-wide checklist below is the architecture. This one is what to check on the specific page in front of you before it ships."),
  ("ol", ["Run the page's JSON-LD through a structured-data validator. One syntax error silently discards the entire block, with no visible symptom on the page itself.",
          "Confirm every FAQPage question and answer appears verbatim as visible text on the same page — not paraphrased, not reordered.",
          "Confirm <code>author</code> and <code>publisher</code> resolve to the canonical <code>@id</code>, not a redefinition of the Person object.",
          "Read each section as if it were the only text retrieved. If it needs the section before it to make sense, it will not survive chunking.",
          "Confirm the page is in <code>sitemap.xml</code>, and that <code>llms-full.txt</code>, if it references this page, says nothing that contradicts it.",
          "Confirm <code>robots.txt</code> has not accidentally blocked a crawler this specific page is meant to reach.",
          "Once genuinely live, ping IndexNow, or accept it will be picked up on the next scheduled crawl."]),
  ("h2", "A checklist that fits on one screen"),
  ("ol", ["One canonical Person or Organization node with a stable <code>@id</code> and a full <code>sameAs</code> list, defined once and referenced from every page.",
          "Article or TechArticle schema on every content page, with <code>author</code> and <code>publisher</code> pointing at that <code>@id</code>.",
          "BreadcrumbList on every page below the root.",
          "FAQPage that mirrors visible on-page text exactly, generated from the same source.",
          "<code>llms.txt</code> and <code>llms-full.txt</code> at the root, consistent with the site.",
          "<code>robots.txt</code> with an explicit, deliberate decision for each named AI agent, plus a sitemap line.",
          "Question-shaped headings, answer-first paragraphs, self-contained sections.",
          "A current <code>sitemap.xml</code> listing every real page, submitted to Search Console.",
          "IndexNow ping wired into the publish step.",
          "Validate JSON-LD on every deploy — one syntax error silently discards the whole block."]),
  ("p", 'This site implements the full list, which is the only reason I can describe it concretely: the canonical Person node lives on the homepage and every page references it, <a href="/llms.txt">/llms.txt</a> and <a href="/llms-full.txt">/llms-full.txt</a> are generated alongside the pages, <a href="/ai.txt">/ai.txt</a> and robots.txt state the crawler policy explicitly, and every guide — including this one — carries TechArticle plus BreadcrumbList plus an FAQPage generated from the same Python list as its visible FAQ section below, so the two cannot drift because they are, literally, the same data rendered twice. <a href="/about.html">The entity page is here →</a>'),
 ],
 "tools": [("/about.html", "About", "the canonical entity page every schema node on this site points at."),
           ("/guides/rag-explained.html", "RAG explained", "how retrieval actually chunks and ranks your pages — useful context for all of this."),
           ("/stack.html", "My stack", "the generator and tooling behind the structured data here."),
           ("/apps.html", "Apps hub", "an example of the same schema pattern applied to product pages.")],
 "faqs": [
  ("What is generative engine optimization (GEO)?", "GEO, also called answer engine optimization or AEO, is the practice of structuring a site so AI answer engines can retrieve, understand, and cite it. It shifts the goal from ranking in a list of links to being the passage a model can lift verbatim and attribute with confidence."),
  ("Why does entity consolidation matter for AI search?", "Because a retrieval system needs to be certain who a site is about. Defining one canonical schema.org Person or Organization node with a stable @id, and referencing that @id from every other page rather than redefining it, turns ten weakly-connected entities into one entity with ten pieces of supporting evidence. A sameAs list linking authoritative profiles ties it to the wider graph."),
  ("What is llms.txt?", "llms.txt is a proposed convention: a markdown file at the site root giving language models a clean, navigable summary of the site without HTML or navigation, with llms-full.txt holding the expanded content. Adoption is not universal, so treat it as cheap insurance, and never let it say anything that contradicts the rendered pages."),
  ("Which AI crawlers should robots.txt address?", "At minimum GPTBot and OAI-SearchBot from OpenAI, ClaudeBot and Claude-SearchBot from Anthropic, PerplexityBot, Google-Extended, Applebot-Extended, Bingbot, and CCBot. Training crawlers and live-retrieval crawlers are separate agents, so decide them independently — blocking Google-Extended does not affect Google Search ranking, and blocking retrieval bots guarantees you will not be cited."),
  ("Does FAQPage schema have to match the visible page?", "Yes. Every question and answer in FAQPage markup must appear as visible text on the same page. Schema-only FAQ content violates Google's structured data guidelines and is a known cause of manual actions, so generate the visible FAQ and the JSON-LD from a single source to prevent drift."),
  ("What is IndexNow?", "IndexNow is a protocol supported by Bing, Yandex, and others that lets a site push changed URLs for immediate recrawl instead of waiting to be crawled. It matters for AI search because Copilot is built on the Bing index. Google does not participate, so keep a current sitemap submitted in Search Console for that side."),
  ("Should I block AI crawlers from training on my site?", "That is independent of whether you want to be cited. A common, defensible position is blocking the named training crawlers — GPTBot, ClaudeBot, Google-Extended, Applebot-Extended, CCBot — while allowing the named retrieval crawlers — OAI-SearchBot, Claude-SearchBot, PerplexityBot, Bingbot — which keeps content out of future model weights while it stays citable today. Blocking both is a valid full opt-out; blocking neither maximises reach at the cost of no control over future use."),
  ("How do you know if ChatGPT or Perplexity is citing your site?", "There is no single dashboard for this yet, so it has to be assembled from partial signals: asking the tools directly with questions your pages answer, watching server logs for the named retrieval agents like OAI-SearchBot and PerplexityBot, checking for referrer-less traffic spikes to a specific page, and cross-checking Bing Webmaster Tools since Copilot runs on the Bing index. Treat the result as directional, not exact."),
 ],
},

]

# Visible FAQ cards mirror the FAQPage JSON-LD exactly - schema-only FAQ content
# violates Google's structured-data guidelines, so the two can never drift.
for _g in GUIDES:
    _g["faq_cards"] = list(_g["faqs"])
